-- Pure synthetic cases. No application tables are changed.
DO $unit$
DECLARE
 base_n constant jsonb:='{"due_date":"2026-10-20","closing_date":"2026-10-07","provider_updated_at":"2026-10-16T18:07:24.150Z","warnings":[]}'::jsonb;
 base_r constant jsonb:=$raw${"updatedAt":"2026-10-16T18:07:24.150Z","payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}],"financeCharges":[]}$raw$::jsonb;
 cases constant jsonb:=$cases$[{"id":"valid_iso_header_and_payment","header":true,"payments":true},{"id":"date_only_payment","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":true},{"id":"valid_offset_revision","n":{"provider_updated_at":"2026-10-16T15:07:24-03:00"},"header":true,"payments":true},{"id":"leap_day","n":{"due_date":"2028-02-29"},"header":true,"payments":true},{"id":"impossible_due","n":{"due_date":"2026-02-31"},"header":false,"payments":false},{"id":"non_leap_february","n":{"due_date":"2026-02-29"},"header":false,"payments":false},{"id":"invalid_month","n":{"due_date":"2026-13-01"},"header":false,"payments":false},{"id":"relative_due_not_allowed","n":{"due_date":"tomorrow"},"header":false,"payments":false},{"id":"wrong_due_json_type","n":{"due_date":20261020},"header":false,"payments":false},{"id":"absent_due_uses_typed_fallback","delete_n":["due_date"],"header":true,"payments":true},{"id":"infinite_fallback_blocked","delete_n":["due_date"],"fallback":"infinity","header":false,"payments":false},{"id":"bad_closing_date","n":{"closing_date":"2026-04-31"},"header":false,"payments":false},{"id":"optional_closing_absent","delete_n":["closing_date"],"header":true,"payments":true},{"id":"warnings_object","n":{"warnings":{}},"header":false,"payments":false},{"id":"warnings_null","n":{"warnings":null},"header":false,"payments":false},{"id":"warnings_not_clear","n":{"warnings":["uncertain_due"]},"header":false,"payments":false},{"id":"warning_field_absent","delete_n":["warnings"],"header":true,"payments":true},{"id":"revision_without_timezone","n":{"provider_updated_at":"2026-10-16T18:07:24"},"header":false,"payments":false},{"id":"invalid_revision_calendar","n":{"provider_updated_at":"2026-02-31T18:07:24Z"},"header":false,"payments":false},{"id":"invalid_revision_offset","n":{"provider_updated_at":"2026-10-16T18:07:24+01:60"},"header":false,"payments":false},{"id":"offset_exceeds_14","n":{"provider_updated_at":"2026-10-16T18:07:24+14:01"},"header":false,"payments":false},{"id":"hour_24_not_issuer_iso","n":{"provider_updated_at":"2026-10-16T24:00:00Z"},"header":false,"payments":false},{"id":"raw_issuer_revision_fallback","delete_n":["provider_updated_at"],"header":true,"payments":true},{"id":"collection_clock_cannot_prove_issuer_revision","delete_n":["provider_updated_at"],"delete_r":["updatedAt"],"n":{"source_sync_at":"2026-10-17T23:59:59Z"},"header":false,"payments":false},{"id":"invalid_primary_revision_does_not_fall_through","n":{"provider_updated_at":"invalid"},"header":false,"payments":false},{"id":"empty_payments","r":{"payments":[]},"header":true,"payments":true},{"id":"missing_payments","delete_r":["payments"],"header":true,"payments":false},{"id":"payments_object","r":{"payments":{}},"header":true,"payments":false},{"id":"payment_missing_id","r":{"payments":[{"id":"","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":false},{"id":"payment_foreign_currency","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"USD"}]},"header":true,"payments":false},{"id":"payment_nan","r":{"payments":[{"id":"pay-a","amount":"NaN","valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":false},{"id":"unknown_payment_type","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"UNKNOWN","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":false},{"id":"observed_other_payment_type","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"OTHER_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":true},{"id":"malformed_payment_calendar","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-02-31","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":false},{"id":"malformed_payment_time","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T99:00:00Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":false},{"id":"valid_and_invalid_payment_taints_proof","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"pay-b","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"USD"}]},"header":true,"payments":false},{"id":"identical_payment_retry_is_idempotent","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":true},{"id":"conflicting_payment_retry","r":{"payments":[{"id":"pay-a","amount":100,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"},{"id":"pay-a","amount":200,"valueType":"FULL_PAYMENT","paymentDate":"2026-09-20T00:00:00.000Z","paymentMode":"DEBIT_ACCOUNT","currencyCode":"BRL"}]},"header":true,"payments":false},{"id":"non_object_payment","r":{"payments":[null]},"header":true,"payments":false},{"id":"raw_not_object","raw_override":[],"header":false,"payments":false},{"id":"normalized_not_object","normalized_override":[],"header":false,"payments":false}]$cases$::jsonb;
 c jsonb;n jsonb;r jsonb;v record;k text;checked integer:=0;
BEGIN
 FOR c IN SELECT value FROM jsonb_array_elements(cases) LOOP
  n:=CASE WHEN c ? 'normalized_override' THEN c->'normalized_override' ELSE base_n||coalesce(c->'n','{}'::jsonb) END;
  r:=CASE WHEN c ? 'raw_override' THEN c->'raw_override' ELSE base_r||coalesce(c->'r','{}'::jsonb) END;
  FOR k IN SELECT jsonb_array_elements_text(coalesce(c->'delete_n','[]'::jsonb)) LOOP n:=n-k;END LOOP;
  FOR k IN SELECT jsonb_array_elements_text(coalesce(c->'delete_r','[]'::jsonb)) LOOP r:=r-k;END LOOP;
  SELECT * INTO STRICT v FROM public.lts_bill_source_fields_v286(n,r,coalesce(c->>'fallback','2026-10-20')::date);
  IF v.header_valid IS DISTINCT FROM (c->>'header')::boolean OR v.payments_valid IS DISTINCT FROM (c->>'payments')::boolean
  THEN RAISE EXCEPTION 'Source case %: header %, payments %, reason %',c->>'id',v.header_valid,v.payments_valid,v.reason;END IF;
  IF v.header_valid AND (v.due_date IS NULL OR v.source_updated_at IS NULL) THEN RAISE EXCEPTION 'Valid header lacks exact dates in %',c->>'id';END IF;
  checked:=checked+1;
 END LOOP;
 IF has_function_privilege('anon','public.lts_bill_source_fields_v286(jsonb,jsonb,date)','EXECUTE')
 OR has_function_privilege('authenticated','public.lts_bill_source_fields_v286(jsonb,jsonb,date)','EXECUTE')
 OR NOT has_function_privilege('service_role','public.lts_bill_source_fields_v286(jsonb,jsonb,date)','EXECUTE')
 OR has_function_privilege('anon','public.lts_current_received_card_bills_v263(uuid)','EXECUTE')
 OR has_function_privilege('authenticated','public.lts_current_received_card_bills_v263(uuid)','EXECUTE')
 THEN RAISE EXCEPTION 'Private helper access changed';END IF;
 PERFORM set_config('lts.bill_source_unit',jsonb_build_object('pass',true,'cases',checked,'private_acl',true)::text,true);
END $unit$;
SELECT current_setting('lts.bill_source_unit')::jsonb AS result;
